update_rule.pseudocode:
if current_day in policy_type_sequence.day:
  new_policy = policy_type_sequence[current_day]
  Government.policy_state = new_policy.policy
  # Apply compliance boost via a transient flag used by decision module
  broadcast policy_compliance_boost for next 3 days
# Enforcement scaling remains at configured enforcement_level
for workplace in Workplaces:
  workplace.mask_policy = (Government.policy_state in ['recommendation','mandate']) and Bernoulli(workplace_policy_adoption_rate)
for place in PublicSpaces:
  place.mask_policy = (Government.policy_state in ['recommendation','mandate'])

init counters work_maskers=0, work_total=0, pub_maskers=0, pub_total=0, actions=0
for person in Persons:
  draw r ~ Uniform[0,1]
  if r < location_visit_rate_work and person.workplace_id:
    location = Workplace(person.workplace_id)
    work_total += 1; work_maskers += person.mask_wearing_state
    if location.mask_policy and not person.mask_wearing_state:
      p_detect = base_detection_prob * Government.enforcement_level * location.enforcement_strength
      if Bernoulli(p_detect):
        if person.enforcement_history.warnings > 0 and Bernoulli(warning_to_fine_escalation_prob):
          person.enforcement_history.fines += 1; actions += 1
        else:
          person.enforcement_history.warnings += 1; actions += 1
  elif r < location_visit_rate_work + location_visit_rate_public:
    location = sample PublicSpace by capacity
    pub_total += 1; pub_maskers += person.mask_wearing_state
    if location.mask_policy and not person.mask_wearing_state:
      p_detect = base_detection_prob * Government.enforcement_level * location.enforcement_strength
      if Bernoulli(p_detect):
        if person.enforcement_history.warnings > 0 and Bernoulli(warning_to_fine_escalation_prob):
          person.enforcement_history.fines += 1; actions += 1
        else:
          person.enforcement_history.warnings += 1; actions += 1
  else:
    pass # home
log work_rate = work_maskers/max(1,work_total), public_rate = pub_maskers/max(1,pub_total)
write logs.public_observed_mask_rate[person] for SocialInfluenceModule (aggregate)

purchases=0; stockouts=0
for retailer in Retailers:
  retailer.stock_level += round(retailer_restock_rate * retailer.stock_level)
  if retailer.stock_level==0: stockouts += 1
aggregate_demand = 0
for person in Persons:
  need = 1 if person.mask_wearing_state and person.mask_ownership==0 else 0
  if need:
    # logit buy prob with price and income
    affordability = sigmoid(income_price_sensitivity(person.income) - price_elasticity_of_demand * avg_retail_price())
    if Bernoulli(affordability):
      r = select retailer with nearest location and available stock (or random)
      if r.stock_level > 0:
        r.stock_level -= 1; person.mask_ownership += 1; purchases += 1
      else:
        stockouts += 1
# Price update by simple inventory rule
for r in Retailers:
  inv_ratio = r.stock_level / max(1, population_size * initial_mask_stock_per_person / len(Retailers))
  r.price = clamp(r.price * (1 + (-price_elasticity_of_demand) * (0.5 - inv_ratio)), 0.5, 5.0)
